-- Core schema for Church Management System.
create extension if not exists pgcrypto;
create schema if not exists private;

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,phone text,preferred_language text not null default 'en',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.churches(id uuid primary key default gen_random_uuid(),legal_name text not null,display_name text not null,country_code char(2) not null default 'PK',currency_code char(3) not null default 'PKR',timezone text not null default 'Asia/Karachi',preferred_language text not null default 'en',logo_path text,header_text text,footer_text text,address text,email text,phone text,website text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.church_branches(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,name text not null,branch_code text,address text,phone text,is_head_office boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),unique(church_id,branch_code));
create table public.church_members(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('owner','admin','pastor','accountant','secretary','ministry_leader','staff','volunteer','member')),status text not null default 'active' check(status in('invited','active','suspended','left')),branch_id uuid references public.church_branches(id) on delete set null,created_at timestamptz not null default now(),unique(church_id,user_id));
create table public.families(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,family_number text,family_name text not null,address text,phone text,family_head_member_id uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(church_id,family_number));
create table public.members(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,family_id uuid references public.families(id) on delete set null,member_number text,first_name text not null,middle_name text,last_name text,gender text check(gender in('female','male','other','unspecified')),date_of_birth date,phone text,email text,address text,identity_type text,identity_last4 text,photo_path text,membership_status text not null default 'active' check(membership_status in('visitor','candidate','active','transferred','inactive','deceased')),joined_on date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(church_id,member_number));
alter table public.families add constraint families_family_head_member_id_fkey foreign key(family_head_member_id) references public.members(id) on delete set null;
create table public.family_relationships(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,family_id uuid not null references public.families(id) on delete cascade,member_id uuid not null references public.members(id) on delete cascade,relationship text not null check(relationship in('head','spouse','son','daughter','parent','grandparent','dependent','other')),is_primary_contact boolean not null default false,created_at timestamptz not null default now(),unique(family_id,member_id));
create table public.certificate_templates(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,certificate_type text not null,name text not null,language_code text not null default 'en',page_size text not null default 'A4',orientation text not null default 'landscape',logo_path text,background_path text,header_text text,footer_text text,pastor_name text,pastor_signature_path text,seal_path text,design_json jsonb not null default '{}'::jsonb,is_default boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.certificate_document_requirements(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,certificate_type text not null,document_code text not null,document_label text not null,description text,is_required boolean not null default true,applicable_country char(2),accepted_mime_types text[] not null default array['application/pdf','image/jpeg','image/png'],max_file_size_bytes bigint not null default 10485760,sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),unique(church_id,certificate_type,document_code,applicable_country));
create table public.certificates(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,certificate_type text not null check(certificate_type in('marriage','birth','death','baptism','family','membership','dedication','confirmation','ordination','transfer','funeral','recommendation','volunteer')),registration_number text not null,status text not null default 'draft' check(status in('draft','documents_pending','submitted','under_review','approved','issued','rejected','cancelled','superseded')),primary_member_id uuid references public.members(id) on delete set null,secondary_member_id uuid references public.members(id) on delete set null,family_id uuid references public.families(id) on delete set null,primary_person_name text not null,secondary_person_name text,event_date date,event_place text,pastor_name text,witness_details jsonb not null default '[]',form_data jsonb not null default '{}',notes text,applicant_user_id uuid references auth.users(id) on delete set null,reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,issued_by uuid references auth.users(id) on delete set null,issued_at timestamptz,issued_pdf_path text,template_snapshot jsonb,qr_verification_token uuid not null default gen_random_uuid(),supersedes_certificate_id uuid references public.certificates(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(church_id,registration_number),unique(qr_verification_token));
create table public.certificate_attachments(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,certificate_id uuid not null references public.certificates(id) on delete cascade,requirement_id uuid references public.certificate_document_requirements(id) on delete set null,document_code text not null,original_file_name text not null,storage_path text not null,mime_type text not null,file_size_bytes bigint not null,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),reviewer_notes text,uploaded_by uuid references auth.users(id) on delete set null,reviewed_by uuid references auth.users(id) on delete set null,uploaded_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.certificate_history(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,certificate_id uuid not null references public.certificates(id) on delete cascade,action text not null,from_status text,to_status text,details jsonb not null default '{}',performed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.church_services(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,title text not null,service_type text,starts_at timestamptz not null,ends_at timestamptz,location text,created_at timestamptz not null default now());
create table public.attendance_records(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,service_id uuid references public.church_services(id) on delete cascade,member_id uuid references public.members(id) on delete set null,visitor_name text,check_in_at timestamptz not null default now(),attendance_method text not null default 'manual',notes text);
create table public.ministries(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,name text not null,description text,leader_member_id uuid references public.members(id) on delete set null,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.ministry_members(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,ministry_id uuid not null references public.ministries(id) on delete cascade,member_id uuid not null references public.members(id) on delete cascade,ministry_role text,joined_at date not null default current_date,unique(ministry_id,member_id));
create table public.church_events(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,title text not null,description text,event_type text,starts_at timestamptz not null,ends_at timestamptz,location text,created_at timestamptz not null default now());
create table public.pastoral_requests(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,member_id uuid references public.members(id) on delete set null,assigned_pastor_user_id uuid references auth.users(id) on delete set null,request_type text not null,subject text,private_notes text,status text not null default 'open' check(status in('open','in_progress','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.financial_accounts(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,name text not null,account_type text not null check(account_type in('cash','bank','mobile_wallet','other')),currency_code char(3) not null default 'PKR',opening_balance numeric(14,2) not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.donations(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,account_id uuid references public.financial_accounts(id) on delete set null,member_id uuid references public.members(id) on delete set null,donor_name text,donation_type text not null check(donation_type in('tithe','offering','general','mission','building','charity','pledge','other')),amount numeric(14,2) not null check(amount>0),currency_code char(3) not null default 'PKR',donated_at timestamptz not null default now(),receipt_number text,payment_method text,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(church_id,receipt_number));
create table public.expenses(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,account_id uuid references public.financial_accounts(id) on delete set null,expense_category text not null,description text not null,amount numeric(14,2) not null check(amount>0),currency_code char(3) not null default 'PKR',spent_at timestamptz not null default now(),receipt_path text,approved_by uuid references auth.users(id) on delete set null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.church_assets(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,branch_id uuid references public.church_branches(id) on delete set null,asset_code text,name text not null,category text,purchase_date date,purchase_cost numeric(14,2),condition text,location text,assigned_to_member_id uuid references public.members(id) on delete set null,notes text,created_at timestamptz not null default now(),unique(church_id,asset_code));
create table public.notifications(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,title text not null,body text,notification_type text,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,actor_user_id uuid references auth.users(id) on delete set null,action text not null,table_name text not null,record_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());

create index idx_church_members_user on public.church_members(user_id,status);
create index idx_members_church_name on public.members(church_id,last_name,first_name);
create index idx_certificates_church_type_date on public.certificates(church_id,certificate_type,event_date desc);
create index idx_certificate_attachments_certificate on public.certificate_attachments(certificate_id);
create index idx_donations_church_date on public.donations(church_id,donated_at desc);
create index idx_expenses_church_date on public.expenses(church_id,spent_at desc);
create index idx_audit_logs_church_created on public.audit_logs(church_id,created_at desc);

do $$ declare t text; begin foreach t in array array['profiles','churches','church_branches','church_members','families','members','family_relationships','certificate_templates','certificate_document_requirements','certificates','certificate_attachments','certificate_history','church_services','attendance_records','ministries','ministry_members','church_events','pastoral_requests','financial_accounts','donations','expenses','church_assets','notifications','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create policy profiles_select_self on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy profiles_insert_self on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy church_members_select_self on public.church_members for select to authenticated using(user_id=(select auth.uid()));
create policy churches_select_member on public.churches for select to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=churches.id and cm.user_id=(select auth.uid()) and cm.status='active'));

do $$
declare t text;
begin
 foreach t in array array['church_branches','families','members','family_relationships','certificate_templates','certificate_document_requirements','certificates','certificate_attachments','church_services','attendance_records','ministries','ministry_members','church_events'] loop
 execute format('create policy %I on public.%I for all to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=%I.church_id and cm.user_id=(select auth.uid()) and cm.status=''active'')) with check(exists(select 1 from public.church_members cm where cm.church_id=%I.church_id and cm.user_id=(select auth.uid()) and cm.status=''active''))',t||'_member_all',t,t,t);
 end loop;
end $$;
create policy pastoral_requests_restricted_select on public.pastoral_requests for select to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and (cm.role in('owner','admin','pastor') or pastoral_requests.assigned_pastor_user_id=(select auth.uid()))));
create policy pastoral_requests_restricted_insert on public.pastoral_requests for insert to authenticated with check(exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor')));
create policy pastoral_requests_restricted_update on public.pastoral_requests for update to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor'))) with check(exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor')));
do $$ declare t text; begin foreach t in array array['financial_accounts','donations','expenses'] loop execute format('create policy %I on public.%I for all to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=%I.church_id and cm.user_id=(select auth.uid()) and cm.status=''active'' and cm.role in(''owner'',''admin'',''accountant''))) with check(exists(select 1 from public.church_members cm where cm.church_id=%I.church_id and cm.user_id=(select auth.uid()) and cm.status=''active'' and cm.role in(''owner'',''admin'',''accountant'')))',t||'_finance_all',t,t,t); end loop; end $$;
create policy church_assets_member_all on public.church_assets for all to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=church_assets.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','staff'))) with check(exists(select 1 from public.church_members cm where cm.church_id=church_assets.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','staff')));
create policy notifications_own_all on public.notifications for all to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.church_members cm where cm.church_id=notifications.church_id and cm.user_id=(select auth.uid()) and cm.status='active')) with check(user_id=(select auth.uid()) and exists(select 1 from public.church_members cm where cm.church_id=notifications.church_id and cm.user_id=(select auth.uid()) and cm.status='active'));
create policy audit_logs_admin_select on public.audit_logs for select to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=audit_logs.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin')));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('church-private-documents','church-private-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy church_docs_member_read on storage.objects for select to authenticated using(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active'));
create policy church_docs_member_upload on storage.objects for insert to authenticated with check(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active'));
create policy church_docs_member_update on storage.objects for update to authenticated using(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active')) with check(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active'));
